// mep's Octave formatter, driven directly.
//
// `mep-octave-format-test` runs the checks below;
// `mep-octave-format-test --format [-w N] [--indent N] [--mh-style] FILE...` prints each file
// formatted ('-' reads stdin), for tools/format_compare.py. Generated by
// tools/new_language.py.
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>

#include "octave_format.h"

namespace {
int g_checks = 0;

void Check(bool ok, const char *expr, int line) {
    g_checks++;
    if (ok) return;
    std::fprintf(stderr, "CHECK FAILED: %s at %s:%d\n", expr, __FILE__, line);
    std::abort();
}
#define CHECK(c) Check((c), #c, __LINE__)

int FormatFiles(int argc, char **argv) {
    octavefmt::Options opts;
    int status = 0;
    for (int k = 2; k < argc; k++) {
        const std::string arg = argv[k];
        if ((arg == "-w" || arg == "--width") && k + 1 < argc) {
            opts.width = std::atoi(argv[++k]);
            continue;
        }
        if (arg == "--indent" && k + 1 < argc) {
            opts.indent = std::atoi(argv[++k]);
            continue;
        }
        if (arg == "--mh-style") {  // exactly what one `mh_style --fix` run writes
            opts.add_semicolons = true;
            opts.converge = false;
            continue;
        }
        std::stringstream ss;
        if (arg == "-") {
            ss << std::cin.rdbuf();
        } else {
            std::ifstream in(arg, std::ios::binary);
            ss << in.rdbuf();
        }
        const octavefmt::Result r = octavefmt::Format(ss.str(), opts);
        if (!r.ok) {
            std::fprintf(stderr, "%s:%d: %s\n", arg.c_str(), r.error_line, r.error.c_str());
            status = 1;
            continue;
        }
        std::fwrite(r.text.data(), 1, r.text.size(), stdout);
    }
    return status;
}

std::string F(const std::string &src, bool semicolons = false) {
    octavefmt::Options o;
    o.add_semicolons = semicolons;
    const octavefmt::Result r = octavefmt::Format(src, o);
    if (!r.ok) return "ERROR: " + r.error;
    return r.text;
}

void TestLayout() {
    // Indentation: function bodies, blocks, switch cases twice.
    CHECK(F("function r = f(x)\nif x\nr = 1;\nelse\nr = 2;\nend\nend\n") ==
          "function r = f(x)\n    if x\n        r = 1;\n    else\n        r = 2;\n    end\nend\n");
    CHECK(F("switch x\ncase 1\ny = 2;\notherwise\ny = 3;\nend\n") ==
          "switch x\n    case 1\n        y = 2;\n    otherwise\n        y = 3;\nend\n");
    // Whitespace around operators, after commas, none inside brackets or around ':' and '^'.
    CHECK(F("x=a+b*c.^ 2;\ny = f( a,b );\nz = v(1 : 3);\n") ==
          "x = a + b * c.^2;\ny = f(a, b);\nz = v(1:3);\n");
    // Unary operators and transposes.
    CHECK(F("w = a+ -b' ;\n") == "w = a + -b';\n");
    // Comments get a space; block comments are left alone.
    CHECK(F("x = 1;%c\n#d\n%{\n  raw\n%}\n") == "x = 1; % c\n# d\n%{\n  raw\n%}\n");
    // One statement per line; redundant brackets go.
    CHECK(F("if (x>0), y = 1; end\n") == "if x > 0\n    y = 1;\nend\n");
    CHECK(F("for i=1:3 disp(i), end\n") == "for i = 1:3\n    disp(i)\nend\n");
    CHECK(F("z = f((a+b), c);\n") == "z = f(a + b, c);\n");
    // Spurious row separators.
    CHECK(F("y = {1, 2,};\nx = [1 2;\n3 4;];\n") == "y = {1, 2};\nx = [1 2\n     3 4];\n");
    // Blank lines: at most one, none at the start, one around functions.
    CHECK(F("\n\nx = 1;\n\n\n\ny = 2;\n") == "x = 1;\n\ny = 2;\n");
    CHECK(F("function a()\nend\nfunction b()\nend\n") == "function a()\nend\n\nfunction b()\nend\n");
    // Continuation lines align with their bracket.
    CHECK(F("a = f(1, ...\n2);\n") == "a = f(1, ...\n      2);\n");
    // Tabs, trailing whitespace, CRLF, the final newline.
    CHECK(F("if x\r\n\ty = 1;  \r\nend") == "if x\n    y = 1;\nend\n");
    // Octave's own syntax.
    CHECK(F("do\nx++;\nuntil x > 3\nunwind_protect\na = 1;\nunwind_protect_cleanup\nb = 2;\nend_unwind_protect\n") ==
          "do\n    x++;\nuntil x > 3\nunwind_protect\n    a = 1;\nunwind_protect_cleanup\n    b = 2;\nend_unwind_protect\n");
    CHECK(F("if x\ny = 1;\nendif\n") == "if x\n    y = 1;\nendif\n");
    // Octave-only: a bracketed condition over lines keeps its brackets, postfix ++ hugs its
    // operand, and a comment line inside a `...` statement does not end it.
    CHECK(F("if (a\n    || b)\nc = 1;\nend\n") == "if (a\n    || b)\n    c = 1;\nend\n");
    CHECK(F("if (r++ == n)\nx = r ++ + 1;\nend\n") == "if r++ == n\n    x = r++ + 1;\nend\n");
    CHECK(F("x = a | ...\n    ## c\n    b;\n") == "x = a | ...\n    ## c\n    b;\n");
    CHECK(F("f = [a; ...\n     # c\n     b];\n") == "f = [a; ...\n     # c\n     b];\n");
}

void TestSemicolons() {
    // Off (the default): what Octave prints does not change.
    CHECK(F("x = 1\ny = 2, z = 3\n") == "x = 1\ny = 2\nz = 3\n");
    // mh_style's own rule.
    CHECK(F("x = 1\ny = 2, z = 3\n", true) == "x = 1;\ny = 2;\nz = 3;\n");
    // Extra terminators go either way; properties lose theirs.
    CHECK(F("x = 1;;\n") == "x = 1;\n");
    CHECK(F("classdef c\nproperties\na = 1;\nend\nend\n", false).find("        a = 1\n") != std::string::npos);
}

void TestRefusesAndKeeps() {
    // A syntax error is refused, the input kept.
    const octavefmt::Result bad = octavefmt::Format("x = (1;\n");
    CHECK(!bad.ok && bad.text == "x = (1;\n" && !bad.error.empty());
    // Whitespace-only input is returned as it is.
    CHECK(F("  \n\n") == "  \n\n");
    // Command syntax and strings are left alone.
    CHECK(F("hold on\nformat long\ns = 'a  b';\n") == "hold on\nformat long\ns = 'a  b';\n");
    // Matrix elements stay elements: no space appears inside [a -b].
    CHECK(F("v = [a -b];\n") == "v = [a -b];\n");
}

void TestIdempotent() {
    const char *srcs[] = {
        "function r = f(x)\nif x\nr = sprintf (\"%d\", ...\n             x);\nend\nend\n",
        "x = [1, 2, ...\n3];\n% c\ny = {'a', ...\n'b'};\n",
        "try, a = 1; catch err, disp(err); end\n",
    };
    for (const char *s : srcs) {
        const std::string once = F(s);
        CHECK(once.rfind("ERROR", 0) != 0);
        CHECK(F(once) == once);
    }
}

}  // namespace

int main(int argc, char **argv) {
    if (argc >= 2 && std::strcmp(argv[1], "--format") == 0) return FormatFiles(argc, argv);
    TestLayout();
    TestSemicolons();
    TestRefusesAndKeeps();
    TestIdempotent();
    std::printf("octave_format_test: %d checks passed\n", g_checks);
    return 0;
}
